UNITS = [("KiB", 2 ** 10), ("MiB", 2 ** 20), ("GiB", 2 ** 30), ("TiB", 2 ** 40)]


def format_size(n):
    if n < 1024:
        return f"{n} B"
    unit, size = UNITS[0]
    for candidate_unit, candidate_size in UNITS:
        if n >= candidate_size:
            unit, size = candidate_unit, candidate_size
    tenths = (2 * n * 10 + size) // (2 * size)
    return f"{tenths // 10}.{tenths % 10} {unit}"
